# Removed: promised features that are not built, and price-led copy.
for _k in ("benefitAnalytics", "benefitReciters", "benefitRecitation", "benefitHifz", "benefitAsk", "benefitSupport"):
    S.pop(_k, None)

out = pathlib.Path(__file__).resolve().parents[1] / "app/lib/l10n"
for lang, idx in (("en", 0), ("ar", 1)):
    arb = {"@@locale": lang}
    for k, (en, ar, params) in S.items():
        arb[k] = (en, ar)[idx]
        if lang == "en" and params:
            arb[f"@{k}"] = {"placeholders": {p: {"type": ty} for p, ty in params.items()}}
    (out / f"app_{lang}.arb").write_text(json.dumps(arb, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(len(S), "keys")
